// BigWings + IkeC - Heartfelt / https://www.shadertoy.com/view/ltffzl
// Transpiled to HLSL using Milkwave

#define tx sin(time)*0.5+1 // 0.5 <= tx <= 1.5

// CONV: setting iChannel samplers to default noise texture
#define iChannel0 sampler_stoy_london
//#define iChannel0 sampler_grace
sampler iChannel0;

// CONV: adding helper functions
float mod_conv(float x, float y) { return x - y * floor(x / y); }
float2 mod_conv(float2 x, float2 y) { return x - y * floor(x / y); }
float3 mod_conv(float3 x, float3 y) { return x - y * floor(x / y); }
float4 mod_conv(float4 x, float4 y) { return x - y * floor(x / y); }

#define S(a, b, t) smoothstep(a, b, t)
#define HAS_HEART
#define USE_POST_PROCESSING

#define stime 70
//#define stime 110
#define stimetotal 1.2*stime


float3 N13(float p) {
 float3 p3 = frac(float3(p,p,p) * float3(.1031,.11369,.13787));
 p3 += dot(p3, p3.yzx + 19.19);
 return frac(float3((p3.x + p3.y)*p3.z, (p3.x+p3.z)*p3.y, (p3.y+p3.z)*p3.x));
}

float4 N14(float t) {
 return frac(sin(t*float4(123., 1024., 1456., 264.))*float4(6547., 345., 8799., 1564.));
}

float N(float t) {
 return frac(sin(t*12345.564)*7658.76);
}

float Saw(float b, float t) {
 return S(0., b, t)*S(1., b, t);
}

float2 DropLayer2(float2 uv_conv,  float t) {
 float2 UV = uv_conv;

 uv_conv.y += t*0.75;
 float2 a = float2(6., 1.);
 float2 grid = a*2.;
 float2 id = floor(uv_conv*grid);

 float colShift = N(id.x);
 uv_conv.y += colShift;

 id = floor(uv_conv*grid);
 float3 n = N13(id.x*35.2+id.y*2376.1);
 float2 st = frac(uv_conv*grid)-float2(.5, 0);

 float x = n.x-.5;

 float y = UV.y*20.;
 float wiggle = sin(y+sin(y));
 x += wiggle*(.5-abs(x))*(n.z-.5);
 x *= .7;
 float ti = frac(t+n.z);
 y = (Saw(.85, ti)-.5)*.9+.5;
 float2 p = float2(x, y);

 float d = length((st-p)*a.yx);

 float mainDrop = S(.4, .0, d);

 float r = sqrt(S(1., y, st.y));
 float cd = abs(st.x-x);
 float trail = S(.23*r, .15*r*r, cd);
 float trailFront = S(-.02, .02, st.y-y);
 trail *= trailFront*r*r;

 y = UV.y;
 float trail2 = S(.2*r, .0, cd);
 float droplets = max(0., (sin(y*(1.-y)*120.)-st.y))*trail2*trailFront*n.z;
 y = frac(y*10.)+(st.y-.5);
 float dd = length(st-float2(x, y));
 droplets = S(.3, 0., dd);
 float m = mainDrop+droplets*r*trailFront;

 return float2(m, trail);
}

float StaticDrops(float2 uv_conv,  float t) {
 uv_conv *= 40.;

 float2 id = floor(uv_conv);
 uv_conv = frac(uv_conv)-.5;
 float3 n = N13(id.x*107.45+id.y*3543.654);
 float2 p = (n.xy-.5)*.7;
 float d = length(uv_conv-p);

 float fade = Saw(.025, frac(t+n.z));
 float c = S(.3, 0., d)*frac(n.z*10.)*fade;
 return c;
}

float2 Drops(float2 uv_conv,  float t, float l0, float l1, float l2) {
 float s = StaticDrops(uv_conv, t)*l0;
 float2 m1 = DropLayer2(uv_conv, t)*l1;
 float2 m2 = DropLayer2(uv_conv*1.85, t)*l2;

 float c = s+m1.x+m2.x;
 c = S(.3, 1., c);

 return float2(c, max(m1.y*l0, m2.y*l1));
}

